// See ../engine/BUILDLIC.TXT. IPX length/copy phase from historical MULTI.C.
/* Select only XOR EBX,EBX; ADD ESI,EAX (four compiler-generated bytes).
 * Incoming SI contains the shifted high length byte, EAX the low byte.
 * The existing getpacket loop consumes BX=0 and SI=length. The standalone
 * context performs the real bounded packet copy; its remaining instructions
 * and private RET are unlinked. The outer receiver saves scratch registers.
 * Unsigned addition preserves the low word even if incoming upper ESI bits
 * are unspecified. Valid lengths are at most 546; the input ring has 16384
 * bytes. Empty register identities constrain real values without instructions.
 */
extern volatile short *netinbufplc;
extern volatile char *netinbuf;
extern char getmess[546];
extern unsigned long ebx_value(unsigned long), esi_value(unsigned long);
#pragma aux ebx_value = parm nomemory [ebx] value [ebx] modify exact nomemory [];
#pragma aux esi_value = parm nomemory [esi] value [esi] modify exact nomemory [];
extern unsigned long eax_value(unsigned long);
#pragma aux eax_value = parm nomemory [eax] value [eax] modify exact nomemory [];
void getpacket_length_copy(unsigned long, unsigned long);
#pragma aux getpacket_length_copy parm [esi] [eax] modify exact [eax ebx ecx edx esi edi];
void getpacket_length_copy(unsigned long high, unsigned long low)
{
    unsigned long index = ebx_value(0);
    unsigned long length = esi_value(high + eax_value(low));
    for (; (short)index < (short)length; index = ebx_value(index + 1))
        getmess[(short)index] = netinbuf[(*netinbufplc + (short)index + 2) & 16383];
}
